DO $$
BEGIN
    IF to_regclass('catalog.attribute_values') IS NOT NULL AND to_regclass('catalog.attributes') IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM pg_constraint c
        JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
        WHERE c.conrelid = to_regclass('catalog.attribute_values') AND c.contype = 'f' AND a.attname = 'attribute_id'
    ) THEN
        ALTER TABLE catalog.attribute_values ADD CONSTRAINT fk_attribute_values_attribute_id FOREIGN KEY (attribute_id) REFERENCES catalog.attributes (id) NOT VALID;
        BEGIN
            ALTER TABLE catalog.attribute_values VALIDATE CONSTRAINT fk_attribute_values_attribute_id;
        EXCEPTION WHEN foreign_key_violation THEN
            RAISE NOTICE 'fk_attribute_values_attribute_id left NOT VALID: stored rows of catalog.attribute_values reference missing rows';
        END;
    END IF;
END $$;

